package by.bsuir.device;
import by.bsuir.repair.contract.*; import by.bsuir.repair.runtime.*; import io.grpc.Status; import io.grpc.stub.StreamObserver; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.Instant; import java.util.*;
@Service public class DeviceGrpcService extends DeviceServiceGrpc.DeviceServiceImplBase {
 private final JdbcTemplate jdbc; private final Jsons jsons; private final OutboxService outbox;
 public DeviceGrpcService(JdbcTemplate jdbc,Jsons jsons,OutboxService outbox){this.jdbc=jdbc;this.jsons=jsons;this.outbox=outbox;}
 @Override public void getDevice(JsonMessage req,StreamObserver<JsonMessage> obs){try{var in=jsons.read(req);UUID id=UUID.fromString(jsons.string(in,"id"));var value=find(id);authorize(value,in);jsons.reply(obs,value);}catch(Throwable e){jsons.fail(obs,e);}}
 @Override public void listClientDevices(JsonMessage req,StreamObserver<JsonMessage> obs){try{var in=jsons.read(req);UUID requested=UUID.fromString(Objects.toString(in.getOrDefault("clientId",in.get("currentUserId"))));String role=Objects.toString(in.get("role"),"CLIENT");UUID current=UUID.fromString(jsons.string(in,"currentUserId"));if(role.equals("CLIENT")&&!requested.equals(current))throw new SecurityException("Client can access only own devices");jsons.reply(obs,jdbc.queryForList("select d.id,d.client_id AS \"clientId\",d.brand,d.model,d.serial_number AS \"serialNumber\",d.created_at AS \"createdAt\",c.id AS \"categoryId\",c.name AS \"categoryName\" from devices d join device_categories c on c.id=d.category_id where d.client_id=? order by d.created_at",requested));}catch(Throwable e){jsons.fail(obs,e);}}
 @Override @Transactional public void upsertDevice(JsonMessage req,StreamObserver<JsonMessage> obs){try{var in=jsons.read(req);UUID current=UUID.fromString(jsons.string(in,"currentUserId"));String role=jsons.string(in,"role");UUID owner=role.equals("ADMIN")&&in.get("clientId")!=null?UUID.fromString(in.get("clientId").toString()):current;UUID category=UUID.fromString(jsons.string(in,"categoryId"));if(jdbc.queryForObject("select count(*) from device_categories where id=?",Integer.class,category)==0)throw Status.NOT_FOUND.withDescription("Category not found").asRuntimeException();String idText=jsons.optional(in,"id");UUID id=idText==null?UUID.randomUUID():UUID.fromString(idText);int exists=jdbc.queryForObject("select count(*) from devices where id=?",Integer.class,id);String event;if(exists==0){jdbc.update("insert into devices(id,client_id,category_id,brand,model,serial_number,created_at,updated_at) values(?,?,?,?,?,?,?,?)",id,owner,category,jsons.string(in,"brand"),jsons.string(in,"model"),jsons.string(in,"serialNumber"),java.time.OffsetDateTime.now(java.time.ZoneOffset.UTC),java.time.OffsetDateTime.now(java.time.ZoneOffset.UTC));event="DeviceRegistered";}else{var old=find(id);if(role.equals("CLIENT")&&!old.get("clientId").toString().equals(current.toString()))throw new SecurityException("Device belongs to another client");jdbc.update("update devices set category_id=?,brand=?,model=?,serial_number=?,updated_at=? where id=?",category,jsons.string(in,"brand"),jsons.string(in,"model"),jsons.string(in,"serialNumber"),java.time.OffsetDateTime.now(java.time.ZoneOffset.UTC),id);event="DeviceUpdated";}var value=find(id);outbox.enqueue(EventTopics.DEVICE,event,id,value);jsons.reply(obs,value);}catch(Throwable e){jsons.fail(obs,e);}}
 @Override @Transactional public void upsertCategory(JsonMessage req,StreamObserver<JsonMessage> obs){try{var in=jsons.read(req);if(!"ADMIN".equals(jsons.string(in,"role")))throw new SecurityException("Administrator role is required");String idText=jsons.optional(in,"id");UUID id=idText==null?UUID.randomUUID():UUID.fromString(idText);if(jdbc.queryForObject("select count(*) from device_categories where id=?",Integer.class,id)==0)jdbc.update("insert into device_categories(id,name,active) values(?,?,?)",id,jsons.string(in,"name"),jsons.bool(in,"active",true));else jdbc.update("update device_categories set name=?,active=? where id=?",jsons.string(in,"name"),jsons.bool(in,"active",true),id);jsons.reply(obs,jdbc.queryForMap("select id,name,active from device_categories where id=?",id));}catch(Throwable e){jsons.fail(obs,e);}}
 @Override public void validateOwnership(JsonMessage req,StreamObserver<JsonMessage> obs){try{var in=jsons.read(req);UUID device=UUID.fromString(jsons.string(in,"deviceId"));UUID client=UUID.fromString(jsons.string(in,"clientId"));var value=find(device);boolean owned=value.get("clientId").toString().equals(client.toString());jsons.reply(obs,Map.of("owned",owned,"device",value));}catch(Throwable e){jsons.fail(obs,e);}}
 private Map<String,Object> find(UUID id){var rows=jdbc.queryForList("select d.id,d.client_id AS \"clientId\",d.brand,d.model,d.serial_number AS \"serialNumber\",d.created_at AS \"createdAt\",c.id AS \"categoryId\",c.name AS \"categoryName\" from devices d join device_categories c on c.id=d.category_id where d.id=?",id);if(rows.isEmpty())throw Status.NOT_FOUND.withDescription("Device not found").asRuntimeException();return rows.get(0);}
 private void authorize(Map<String,Object> value,Map<String,Object> in){String role=Objects.toString(in.get("role"),"CLIENT");if(role.equals("CLIENT")&&!value.get("clientId").toString().equals(Objects.toString(in.get("currentUserId"))))throw new SecurityException("Client can access only own devices");}
}


